-- Banco de imagens do Cara a Cara Musical (referência) no Supabase: entidades (artistas/bandas) e as 125 fotos com o que se VÊ em cada uma.
-- JÁ APLICADO (nov/2026). Tabelas fechadas (RLS ligada, sem políticas, sem acesso pra anon/authenticated): só o painel/MCP com a chave de serviço lê.
-- As imagens ficam no repositório (arquivo = assets/figurinhas/fotos/<codigo>.jpeg, conferir pelo sha256); aqui vão só os metadados. rostos/foco ficam em assets/figurinhas/catalogo.json.
-- Códigos T/F/N (verdadeiro/falso/não dá pra afirmar). Fonte: js/jogos/cara-musical/elenco.js + dados-extra.js.
create table if not exists public.cara_entidades (
  id text primary key, nome text not null, curto text not null, origem text, fotos text[] not null default '{}', attrs jsonb not null default '{}'::jsonb, atualizado_em timestamptz not null default now());
create table if not exists public.cara_fotos (
  codigo text primary key, arquivo text generated always as ('assets/figurinhas/fotos/' || codigo || '.jpeg') stored, sha256 text, entidade_id text references public.cara_entidades(id), artista_banda text, colecao text, secao text, raridade text, modelo text,
  largura_px int, altura_px int, preto_e_branco boolean, varias boolean, instrumento boolean, atualizado_em timestamptz not null default now());
create index if not exists cara_fotos_entidade on public.cara_fotos(entidade_id);
alter table public.cara_entidades enable row level security; alter table public.cara_fotos enable row level security;
revoke all on public.cara_entidades, public.cara_fotos from anon, authenticated;
comment on table public.cara_fotos is 'true/false/null: null = não dá pra afirmar pela imagem. varias = mais de uma pessoa; instrumento = guitarra, baixo, bateria ou baquetas aparecendo.';
insert into public.cara_entidades (id,nome,curto,origem,fotos,attrs)
select v.id,v.nome,v.curto,v.origem,v.fotos,(select jsonb_object_agg(k, case substr(v.cod,i::int,1) when 'T' then true when 'F' then false else null end) from unnest(array['banda','solo','dupla','brasileiro','eua','uk','rock','pop','pesado','punk','mpb','baterista','guitarrista','antes1980','depois2000','beatles','cantor','ativo','grande','anos80_90']) with ordinality as t(k,i)) from (values
